<script type="text/javascript">
    var nextapiPath = "../next-api/v1/";

    $('#modal-open').on("change", function (e)
    {
        var body = $('#body')[0];

        if (this.value === 'SI')
        {
            body.style.overflow='hidden';
            $('#btn_menu_utente').css("pointer-events", "none");
            $('#btn_giorno_precedente').attr("disabled", true);
            $('#btn_giorno_successivo').attr("disabled", true);
            $('#btn_calendario').attr("disabled", true);
        }
        else
        {
            body.style.overflow='visible';
            $('#btn_menu_utente').css("pointer-events", "auto");
            $('#btn_giorno_precedente').attr("disabled", false);
            $('#btn_giorno_successivo').attr("disabled", false);
            $('#btn_calendario').attr("disabled", false);
        }
    });

    function toggleSostituzioni(id)
    {
        var elenco = $('#' + id);
        elenco.toggle();
        $('#freccia_' + id).html(elenco.is(':visible') ? '&#9660;' : '&#9654;');
    }

    function chiudiSfondoOscurato()
    {
        $('#sfondo_oscurato').hide();
        $('#form_sostituzioni').hide();
        $('#elenco_sostituzioni').hide();
        $('#modal-open').val('NO').trigger('change');
    }

    function ridimensionaHome(){
        $('#schede_home').css('height', '');
        if ($('#schede_home').height() > $(window.innerHeight)[0] - $('#schede_home').position().top - 10){
            $('#schede_home').height($(window.innerHeight)[0] - $('#schede_home').position().top - 10);
        }
    }

    function apriDettaglioCorso(idCorso) {
        apriDettaglioCorsoCall(idCorso).then((corso) => {
            $("#lista_studenti").html("");
            $("#lista_docenti").html("");
            $("#titolo_corso").html(corso.descrizione);

            var partecipanti = '';
            if (corso.partecipanti.length > 0){
                corso.partecipanti.forEach((stud) => {
                    partecipanti += "<li>" + stud.nome_completo + "</li>";
                });
            } else {
                partecipanti += "<li>Non ci sono partecipanti</li>";
            }
            $("#lista_studenti").append(partecipanti);

            var docenti = '';
            if (corso.professori.length > 0){
                corso.professori.forEach((doc) => {
                    docenti += "<li>" + doc.nome_completo + "</li>";
                });
            } else {
                docenti += "<li>Non ci sono docenti</li>";
            }

            $("#lista_docenti").append(docenti);
            apriChiudiPopup('dettaglio_corso', 'sfondo_oscurato');
        });
    }

    function apriDettaglioCorsoCall(idCorso) {
        $('#jqxGeneralLoader').jqxLoader('open');
        return new Promise((resolve, reject) => {
            $.ajax({
                type: "GET",
                data: {},
                url: nextapiPath + "courses/" + idCorso,
                headers: { 'Authorization': $("[name='current_key']").val() },
                success: function (data) {
                    $('#jqxGeneralLoader').jqxLoader('close');
                    resolve(data);
                },
                error: function (data) {
                    $('#jqxGeneralLoader').jqxLoader('close');
                    creaToast("Errore", 'error');
                    reject(data);
                },
                complete: function (data) {
                    if (data.responseJSON) {

                    } else {
                        console.log($.parseJSON(data.responseJSON));
                        creaToast("Errore", 'error');
                    }
                    $('#jqxGeneralLoader').jqxLoader('close');
                    resolve(data);
                }
            });
        });
    }

